"""Complete 28 original autoinflammatory disease/HLH questions."""
from create_rheum_hlh import rows,q,S,H,AH,ref
from qbank_authoring import finalize
F=ref('EULAR/PReS FMF management: 2024 update, published 2025','https://doi.org/10.1016/j.ard.2025.01.028')
IL=ref('EULAR/ACR IL-1-mediated autoinflammatory disease points to consider','https://pmc.ncbi.nlm.nih.gov/articles/PMC9531906/')
VX=ref('ACR international VEXAS guidance statement','https://pmc.ncbi.nlm.nih.gov/articles/PMC12991921/')

q('A young adult of Mediterranean ancestry has recurrent self-limited 1–3-day fever, peritonitic pain and occasional ankle arthritis, with wellness between attacks. Which diagnosis best fits?', 'Familial Mediterranean fever',[
 ('TRAPS','TRAPS attacks often last longer and commonly have migratory myalgia/rash and periorbital edema.'),('Mevalonate kinase deficiency','Early-onset attacks with lymphadenopathy, GI symptoms and vaccine triggers are more characteristic.'),('PFAPA','Aphthae, pharyngitis and cervical adenitis define a different recurring pattern.')],
 'Recognize short serositis attacks','**FMF is a pyrin-associated autoinflammatory disease commonly linked to MEFV variants.**',['Ancestry supports probability but is not a requirement.','Acute abdominal emergencies must still be evaluated when the episode is atypical.'], '**Use the recurring clinical pattern and appropriate genetic interpretation.**',['Monitor inflammation between attacks.','Prevention aims to control symptoms and long-term amyloid risk.'],[['FMF','Short fever/serositis attacks'],['TRAPS','Often longer attacks'],['PFAPA','Aphthae/pharyngitis/adenitis']],[F,ref('GeneReviews: familial Mediterranean fever','https://www.ncbi.nlm.nih.gov/books/NBK1227/')],style='clinical_scenario')

q('What is the principal long-term treatment for most patients with FMF?', 'Regular colchicine prophylaxis',[
 ('Colchicine only after every attack has completely resolved','The goal is continuous prevention rather than occasional rescue alone.'),('Allopurinol','It lowers urate and does not treat the pyrin-mediated disease.'),('Long-term high-dose prednisone as the usual universal maintenance therapy','This does not provide the standard preventive strategy and adds substantial toxicity.')],
 'Colchicine prevents both attacks and a major complication','**Continuous colchicine reduces inflammatory attacks and AA amyloidosis risk.**',['Dose and monitoring depend on age, renal/hepatic function, interactions and tolerance.','Adherence is crucial before declaring resistance.'], '**Monitor clinical and subclinical inflammation.**',['Serum amyloid A or CRP helps identify persistent activity.','Review proteinuria as a potential amyloid warning.'],[['Colchicine','Continuous prophylaxis'],['Inflammation monitoring','Includes between-attack activity'],['Goal','Attack control and complication prevention']],[F])

q('An FMF patient has new persistent proteinuria after years of uncontrolled inflammation. Which complication is particularly concerning?', 'AA amyloidosis',[
 ('AL amyloidosis as automatically established by FMF','AL requires a light-chain clonal context and is a different amyloid type.'),('Anti-GBM disease as proven from proteinuria alone','This requires a compatible renal syndrome and serological/pathological evidence.'),('Isolated transient exercise proteinuria as certain','Persistent proteinuria in this context needs investigation.')],
 'Chronic serum amyloid A production can lead to AA deposition','**Uncontrolled inflammation can produce AA amyloidosis, often with renal involvement.**',['Proteinuria or nephrotic syndrome may be the first major clue.','Amyloid typing is important because treatment differs by precursor.'], '**Assess kidney function and establish the cause.**',['Control ongoing inflammation and optimize renal care.','Do not assume an amyloid diagnosis without appropriate evidence when other kidney diseases are possible.'],[['AA','Inflammation-associated precursor'],['AL','Light-chain precursor'],['New proteinuria','Requires renal investigation']],[F],style='clinical_scenario')

q('A patient has confirmed FMF with persistent attacks and inflammation despite verified adherence to the maximally tolerated colchicine regimen. Which strategy is appropriate?', 'Consider IL-1-directed treatment while continuing colchicine when tolerated',[
 ('Stop all colchicine automatically and use NSAIDs alone indefinitely','This may leave preventable ongoing inflammation and amyloid risk.'),('Label resistance before reviewing adherence or diagnosis','Apparent resistance can reflect inadequate exposure or a different diagnosis.'),('Add allopurinol to suppress serum amyloid A','This does not target the disease mechanism.')],
 'Verify resistance before escalating','**IL-1 inhibition is an important option in colchicine-resistant or intolerant FMF.**',['Confirm adherence, adequate dosing and the diagnosis.','Persistent biochemical inflammation matters even when attacks are less frequent.'], '**Continue tolerated colchicine where appropriate.**',['Review infection and drug-specific risks before targeted treatment.','Monitor both patient experience and inflammatory markers.'],[['Apparent resistance','Check adherence/exposure'],['Confirmed activity','Consider IL-1 therapy'],['Long-term goal','Suppress subclinical inflammation']],[F],style='clinical_scenario')

q('Prolonged febrile attacks with migratory painful erythema, myalgia, abdominal pain and periorbital edema in an autosomal dominant family suggest which disorder?', 'TNF receptor-associated periodic syndrome',[
 ('FMF','This more typically has shorter serositis attacks and a different genetic association.'),('CAPS','An urticaria-like rash, cold sensitivity and selected neurological/auditory features are more characteristic.'),('Hereditary angioedema','It causes swelling and abdominal attacks but does not best explain this recurrent febrile inflammatory rash/myalgia pattern.')],
 'Attack length and accompanying features refine the periodic-fever differential','**TRAPS is associated with pathogenic TNFRSF1A variants.**',['Penetrance and phenotype vary by variant.','Some low-penetrance findings require careful clinical interpretation.'], '**Assess persistent inflammation and amyloid risk.**',['Use a specialist genetic interpretation rather than assume every variant is causal.','Selected IL-1-directed treatment can control attacks and inflammation.'],[['TRAPS','Longer attacks/periorbital edema'],['Gene','TNFRSF1A'],['Risk','Persistent inflammation/AA amyloid']],[IL],style='clinical_scenario')

q('Which treatment pathway is a principal targeted strategy for persistent TRAPS inflammation?', 'IL-1 inhibition',[
 ('Urate-lowering therapy','This does not address the periodic inflammatory syndrome.'),('Hydroxychloroquine as a proven universal preventive treatment','It is not the principal evidence-based pathway for TRAPS.'),('Routine antibiotic suppression without an infectious trigger','This does not treat the inherited autoinflammatory mechanism.')],
 'The disease name does not mean every TNF inhibitor is the preferred choice','**IL-1 blockade is central in current TRAPS management.**',['Glucocorticoids can relieve selected attacks but are not an ideal chronic strategy.','Drug choice and duration depend on severity, persistent activity and complications.'], '**Assess the patient between attacks as well as during them.**',['Monitor inflammatory markers and proteinuria.','Review treatment response and adverse effects with an expert team.'],[['IL-1 therapy','Targeted inflammatory control'],['Short-term steroids','May relieve an episode'],['Monitoring','Persistent inflammation and amyloid risk']],[IL])

q('Cold-triggered urticaria-like rash, fever, arthralgia and progressive sensorineural hearing loss suggest which disease spectrum?', 'Cryopyrin-associated periodic syndromes',[
 ('TRAPS','Periorbital edema and longer migratory inflammatory attacks are more characteristic.'),('FMF','Short serositis attacks without this typical hearing/rash phenotype are more characteristic.'),('Primary cold urticaria alone','This does not adequately explain sustained systemic inflammation and progressive hearing involvement.')],
 'Recognize the cryopyrin/NLRP3 spectrum','**CAPS includes familial cold autoinflammatory syndrome, Muckle–Wells and severe neonatal-onset phenotypes.**',['NLRP3 inflammasome activation drives IL-1-mediated disease.','Mosaic disease can complicate standard genetic testing.'], '**Assess hearing, eyes, CNS and inflammatory complications.**',['Early disease control can prevent damage.','Do not assume an urticaria-like rash is simply histamine-mediated allergy.'],[['NLRP3','Inflammasome pathway'],['Hearing loss','Important organ clue'],['IL-1 blockade','Disease-directed treatment']],[IL],style='clinical_scenario')

q('Which feature particularly suggests a severe neonatal-onset CAPS phenotype rather than uncomplicated familial cold autoinflammatory syndrome?', 'Chronic aseptic meningitis with raised intracranial pressure and skeletal overgrowth changes',[
 ('Only brief cold-related skin symptoms without organ injury','This is closer to a milder cold-associated phenotype.'),('Isolated first-MTP MSU crystal arthritis','This is gout, not a defining CAPS complication.'),('Only anti-CCP-positive erosive MCP synovitis','This supports a different autoimmune arthritis phenotype.')],
 'The CAPS spectrum ranges from episodic symptoms to damaging chronic inflammation','**Severe CAPS can involve CNS, eyes, hearing and bone.**',['Prompt IL-1-directed treatment can reduce inflammation and prevent progression.','Established structural damage may not fully reverse.'], '**Use organ-specific surveillance.**',['Assess hearing, vision and neurological symptoms regularly.','Escalate care if headaches, papilledema or other intracranial-pressure signs develop.'],[['Mild CAPS','Often episodic cold-associated symptoms'],['Severe CAPS','CNS/bone/eye involvement'],['Early control','Prevents avoidable damage']],[IL])

q('A child has recurrent fever with cervical nodes, diarrhea, abdominal pain and aphthous ulcers, sometimes triggered by vaccination. Which inherited disorder deserves consideration?', 'Mevalonate kinase deficiency',[
 ('TRAPS','The attack pattern and associated features differ, though overlap requires careful assessment.'),('Classic FMF','Serositis-dominant brief attacks are more typical.'),('VEXAS syndrome','This is predominantly an acquired adult-onset hematoinflammatory disorder.')],
 'Recognize an early-onset metabolic autoinflammatory syndrome','**MKD can produce recurrent inflammatory attacks with GI and lymph-node manifestations.**',['Urinary mevalonic acid during an attack and molecular testing can support diagnosis.','Serum IgD is not a sufficiently reliable stand-alone diagnostic test.'], '**Use phenotype and appropriate metabolic/genetic evidence.**',['Exclude infection and other periodic-fever disorders.','IL-1-directed therapy can be used according to severity and specialist guidance.'],[['MKD','MVK-associated disease'],['IgD','Not a decisive test alone'],['Urine/genetics','More informative in the correct context']],[IL],style='clinical_scenario')

q('A child has clockwork recurrent fever with aphthous ulcers, pharyngitis and cervical adenitis, normal growth and wellness between attacks. Which diagnosis best fits after exclusion of relevant mimics?', 'PFAPA',[
 ('Cyclic neutropenia','This is an important mimic but requires serial counts demonstrating the neutrophil cycle.'),('FMF','Serositis and short inflammatory attacks are more characteristic than this triad.'),('CAPS','The cold/urticaria-like auditory or neurological phenotype differs.')],
 'A periodic-fever pattern does not always imply a monogenic diagnosis','**PFAPA is a recognizable recurrent clinical syndrome.**',['Infection, cyclic neutropenia and inherited periodic fevers must be considered when indicated.','A single glucocorticoid dose can abort selected attacks but is not uniquely diagnostic.'], '**Document timing and between-episode health.**',['Treatment can include episodic therapy and selected preventive or surgical approaches.','Atypical growth failure, persistent inflammation or organ disease warrants reconsideration.'],[['PFAPA','Aphthae/pharyngitis/adenitis'],['Cyclic neutropenia','Serial neutrophil assessment'],['Atypical course','Reassess the diagnosis']],[ref('PFAPA international clinical review','https://pmc.ncbi.nlm.nih.gov/articles/PMC8356195/')],style='clinical_scenario')

q('An older man has steroid-dependent fever, auricular chondritis, neutrophilic skin lesions, venous thrombosis and macrocytic anemia. Marrow shows vacuolated myeloid precursors. Which disorder should be tested for?', 'VEXAS syndrome',[
 ('Relapsing polychondritis without hematological disease as the complete explanation','Chondritis can overlap, but macrocytic cytopenia and vacuoles suggest a hematoinflammatory syndrome.'),('Copper deficiency as the only possible diagnosis from vacuoles','Copper deficiency is a marrow mimic, but does not best unify this inflammatory phenotype.'),('FMF','The late acquired hematological/inflammatory pattern is different.')],
 'Connect adult-onset inflammation to a myeloid clone','**VEXAS is associated with somatic pathogenic UBA1 variants.**',['Macrocytic anemia, vacuoles and inflammation are clues but not independently diagnostic.','The disease predominantly affects men, with rare female cases in relevant chromosomal contexts.'], '**Confirm with appropriate blood/marrow molecular testing.**',['Assess MDS, thrombosis and organ inflammation.','Coordinate hematology and rheumatology care.'],[['UBA1','Somatic variant'],['Marrow vacuoles','Clue, not uniquely specific'],['Macrocytosis/inflammation','Important combined phenotype']],[VX],style='clinical_scenario')

q('Which statement best describes definitive treatment prospects in VEXAS?', 'Allogeneic HSCT can be potentially curative in selected patients, but risk is substantial and other treatments mainly control inflammation or the clone',[
 ('Hydroxychloroquine is an established universal cure','No such universal curative effect is established.'),('Every older patient should undergo immediate transplantation regardless of fitness','Selection and competing risks are central.'),('Glucocorticoid responsiveness proves the myeloid clone has disappeared','Symptom suppression is not molecular eradication.')],
 'Distinguish inflammatory control from clone-directed cure','**VEXAS treatment is individualized and often requires management of both inflammation and marrow disease.**',['JAK inhibition or other immune therapies can help selected patients but have important risks.','Azacitidine may be relevant in an appropriate clonal/marrow context.'], '**Discuss transplantation only through a multidisciplinary risk assessment.**',['Age, organ status, infection risk and disease burden affect suitability.','Monitor thrombosis, cytopenias and treatment toxicity over time.'],[['Glucocorticoids/immune therapy','Inflammatory control'],['Clone-directed therapy','Selected hematological contexts'],['Allogeneic HSCT','Potentially curative with substantial risk']],[VX,ref('GeneReviews: VEXAS syndrome','https://www.ncbi.nlm.nih.gov/books/NBK614471/')])

if __name__=='__main__':finalize('Rheumatology',8,'Autoinflammatory Disease and HLH','rheum-autoinflammatory-hlh',rows,28)
